const names=[1,2,3].map(number=>`output/线性代数前两章模拟卷${number}.tex`);
const local=["output/线性代数前两章模拟卷.tex",".question-bank-work/linear-algebra-combined/extra.tex"];
const results=await Promise.allSettled([...names,...local].map(p=>tools.exec_command({cmd:`cat '${p}'`,max_output_tokens:20000})));
if(results.some(r=>r.status!=="fulfilled"||r.value.exit_code!==0)) throw Error("源稿读取失败");
const values=results.map(r=>r.value.output.trimEnd());
const base=values[3].split(/(?=^\\Question)/m).slice(1);
const extra=values[4].split(/(?=^\\Question)/m);
const blocks={};
for(const block of [...base,...extra]){
 const content=block.replace(/^\\end\{document\}\s*$/m,"").trim();
 const key=content.match(/^\\Question\{([^}]+)\}/)?.[1];
 if(!key||blocks[key])throw Error(JSON.stringify(key));
 blocks[key]=content;
}
blocks["16"]=blocks["16"].replace("2013 年数学一第 20 题（原卷第 3 页）","2013 年数学一第 20 题（第 3 页）、数学二第 22 题（第 4 页）");
const groups=[
 ["1","N02","N07","N12","5","7","6","N08","11","N17","16","N15"],
 ["3","N03","N04","N09","N14","14","8","10","N13","N16","N18","N05"],
 ["2","4","N01","N10","N11","12","13","9","15","17","N06"]
];
if(Object.keys(blocks).length!==35||new Set(groups.flat()).size!==35)throw Error("题数或重复检查失败");
store("allExamGroups",groups);
const changes=[];
for(let i=0;i<groups.length;i++){
 const total=groups[i].length;
 const score=total===12?8:10;
 const cover=`\\ExamCover{${total}}{6–${total-2}}{${score}}{${total-1}–${total}}`;
 const questions=groups[i].map((key,index)=>{
  const points=index<5?4:index<total-2?score:20;
  return blocks[key].replace(/^\\Question\{[^}]+\}(\{[^}]+\}\{[^}]+\})\{\d+\}/,`\\Question{${index+1}}$1{${points}}`);
 });
 const output=String.raw`% !TeX program = xelatex
\documentclass[UTF8,zihao=-4,fontset=fandol]{ctexart}
\newcommand{\ExamNumber}{${i+1}}
\usepackage{linear-algebra-exam}

\begin{document}
${cover}

${questions.join("\n\n")}
\end{document}`;
 changes.push(`*** Update File: ${names[i]}`,"@@",...values[i].split("\n").map(line=>"-"+line),...output.split("\n").map(line=>"+"+line));
}
text(await tools.apply_patch(["*** Begin Patch",...changes,"*** End Patch"].join("\n")));

